// Filter items from the past week
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const repo = $input.first().json.repo || "owner/repo";
const lang = $input.first().json.lang || "EN";

// Helper to parse dates from GitHub response
function getDates(items) {
  return (items || []).map(item => {
    const date = item.commit?.commit?.author?.date || item.merged_at || item.closed_at || item.created_at;
    return date ? new Date(date) : null;
  }).filter(d => d && d >= weekAgo);
}

// Commits
const commits = getDates($node["Get Commits"].json.data || []);
// Issues
const issues = getDates($node["Get Closed Issues"].json.data || []);
// PRs
const prs = getDates($input.all().map(n => n.json.data || []).flat() || []);

const summary = {
  repo,
  lang,
  weekStart: weekAgo.toISOString().split('T')[0],
  weekEnd: now.toISOString().split('T')[0],
  commitCount: commits.length,
  issueCount: issues.length,
  prCount: prs.length,
  commits: (commits || []).slice(0, 10).map(c => c.message || c.commit?.message || 'no message'),
  issues: (issues || []).slice(0, 10).map(i => i.title || 'no title'),
  prs: (prs || []).slice(0, 10).map(p => p.title || 'no title')
};

return [{ json: summary }];

